import type { Changes } from '../core/changes.ts';
import { casings, resourceNames, words, type Casings, type ResourceNames } from '../core/names.ts';
import { backendLib } from '../core/workspace.ts';
import { ensureMergedRelations } from '../wiring/backend.ts';
import { apiComment, columnBuilder, type FieldSpec, type OnDelete } from './spec.ts';
import { TableFile } from './table-file.ts';

const TABLES = `${backendLib('database')}/src/tables`;
/** Generated by the Better Auth CLI: the CLI never edits it. */
const AUTH = `${TABLES}/auth.ts`;

export interface FieldResult {
  /** Resources whose table changed (for contract sync). */
  touched: string[];
  /** Columns removed, per resource: the contract sync drops them too. */
  dropped: Record<string, string[]>;
  notes: string[];
  /** Whether a foreign key was added (the migration needs checking). */
  foreignKey: boolean;
}

/** A table: its file, variable and names. */
interface Table {
  path: string;
  variable: string;
  /** SQL name (snake singular), e.g. activity. */
  sql: string;
  names: ResourceNames;
  /** The `<variable>Relations` part, if the file has one. */
  part: string;
}

/** Edits several table files in one run, then hands them to `changes`. */
class Tables {
  private readonly files = new Map<string, TableFile>();
  private readonly changes: Changes;
  constructor(changes: Changes) {
    this.changes = changes;
  }

  file(path: string): TableFile {
    let file = this.files.get(path);
    if (!file) {
      const source = this.changes.read(path);
      if (source === undefined) throw new Error(`${path} not found.`);
      file = new TableFile(path, source);
      this.files.set(path, file);
    }
    return file;
  }

  /** The table of a resource ("activities", "users"…), wherever it's declared. */
  find(resource: string): Table {
    const names = resourceNames(resource);
    const variable = names.s.camel;
    const preferred = `${TABLES}/${names.p.kebab}.ts`;
    const candidates = [
      preferred,
      ...this.changes.list(TABLES)
        .filter((f) => f.endsWith('.ts'))
        .map((f) => `${TABLES}/${f}`),
    ];
    for (const path of candidates) {
      if (!this.changes.exists(path)) continue;
      if (this.file(path).tables().includes(variable))
        return { path, variable, sql: names.s.snake, names, part: `${variable}Relations` };
    }
    throw new Error(`No table "${variable}" in ${TABLES}: create the resource with "dafne-old g backend table ${names.p.kebab}".`);
  }

  /** Table files are always Prettier-formatted: the backend formats them (pnpm format). */
  commit() {
    for (const [path, file] of this.files) this.changes.update(path, () => file.source, { format: true });
  }

  /** Table files with a relations part that has `<table>: { <relation>: ... }`. */
  findRelation(table: string, relation: string): { file: TableFile; part: string; config: string } | undefined {
    for (const name of this.changes.list(TABLES).filter((f) => f.endsWith('.ts'))) {
      const path = `${TABLES}/${name}`;
      const file = this.file(path);
      for (const variable of file.tables()) {
        const part = `${variable}Relations`;
        if (!file.hasRelationsPart(part)) continue;
        const config = file.relations(part, table)[relation];
        if (config) return { file, part, config };
      }
    }
    return undefined;
  }
}

function editable(table: Table) {
  if (table.path === AUTH)
    throw new Error(`${AUTH} is generated by Better Auth (pnpm auth:schema:generate): change the auth config instead.`);
}

/** The column builder for a foreign key to `target`'s primary key. */
function foreignKeyColumn(tables: Tables, target: Table, sqlName: string): { code: string; builder: string } {
  const id = tables.file(target.path).columnCode(target.variable, 'id');
  const length = id?.match(/length:\s*(\d+)/)?.[1];
  if (!id || id.startsWith('varchar')) return { code: `varchar('${sqlName}', { length: ${length ?? 36} })`, builder: 'varchar' };
  if (id.startsWith('int')) return { code: `int('${sqlName}')`, builder: 'int' };
  if (id.startsWith('serial') || id.startsWith('bigint'))
    return { code: `bigint('${sqlName}', { mode: 'number', unsigned: true })`, builder: 'bigint' };
  return { code: `varchar('${sqlName}', { length: 36 })`, builder: 'varchar' };
}

const relativeImport = (from: Table, to: Table) => `./${to.path.split('/').pop()!.replace(/\.ts$/, '.js')}`;
const pascal = (c: Casings) => c.pascal;

export function addField(changes: Changes, resource: string, spec: FieldSpec): FieldResult {
  const tables = new Tables(changes);
  const owner = tables.find(resource);
  editable(owner);
  const result: FieldResult = { touched: [owner.names.p.kebab], dropped: {}, notes: [], foreignKey: false };

  if (spec.type !== 'ref') {
    const key = casings(words(spec.name));
    const file = tables.file(owner.path);
    const { code, imports } = columnBuilder(spec, key.snake);
    for (const name of imports) file.ensureImport('drizzle-orm/mysql-core', name);
    file.addColumn(owner.variable, key.camel, code, apiComment(spec), spec.after);
    if (spec.index) file.addIndex(owner.variable, owner.sql, key.camel);
    if (spec.required && spec.default === undefined)
      result.notes.push(
        `${key.camel} is NOT NULL without a default: the migration fails if ${owner.sql} already has rows. Add --default, or make it nullable first.`,
      );
    tables.commit();
    return result;
  }

  if (!spec.to) throw new Error('A ref field needs --to <resource>, e.g. --to customers.');
  const target = tables.find(spec.to);
  ensureMergedRelations(changes);
  result.foreignKey = true;

  switch (spec.relation) {
    case 'many-to-one':
    case 'one-to-one':
      foreignKey(tables, owner, target, spec, {
        relation: relationName(spec.name),
        inverse: spec.inverse === false ? false : spec.inverse ?? (spec.relation === 'one-to-one' ? owner.names.s.camel : owner.names.p.camel),
        oneToOne: spec.relation === 'one-to-one',
        apiTags: spec.api,
      });
      break;
    case 'one-to-many':
      // The key lives on the other table: <owner>Id there.
      editable(target);
      // --inverse names the relation over there (and so its key).
      foreignKey(tables, target, owner, spec, {
        relation: (spec.inverse || undefined) ?? owner.names.s.camel,
        inverse: spec.name,
        oneToOne: false,
        apiTags: spec.api,
      });
      result.touched.push(target.names.p.kebab);
      break;
    case 'many-to-many':
      manyToMany(tables, owner, target, spec);
      result.notes.push('The junction table has no contract: add the ids to the body by hand if the API sets them.');
      break;
  }
  tables.commit();
  return result;
}

/** "customer" or "customerId" → the relation name, customer. */
const relationName = (name: string) => casings(words(name.replace(/Id$/, ''))).camel;

/**
 * Adds `<relation>Id` to `from`, referencing `to`, with the relation on
 * `from` and (unless `inverse` is false) the reverse one on `to`, both in
 * `from`'s file.
 */
function foreignKey(
  tables: Tables,
  from: Table,
  to: Table,
  spec: FieldSpec,
  options: { relation: string; inverse: string | false; oneToOne: boolean; apiTags: string[] },
) {
  const file = tables.file(from.path);
  if (!file.hasRelationsPart(from.part))
    throw new Error(`${from.path} has no "${from.part}" (defineRelationsPart): add one before adding relations.`);

  const relation = casings(words(options.relation));
  const key = `${relation.camel}Id`;
  const column = foreignKeyColumn(tables, to, `${relation.snake}_id`);
  const onDelete: OnDelete = spec.onDelete ?? (spec.required ? 'restrict' : 'set null');
  if (onDelete === 'set null' && spec.required) throw new Error('--on-delete "set null" needs a nullable field (drop --required).');

  file.ensureImport('drizzle-orm/mysql-core', column.builder);
  if (from.path !== to.path) file.importTable(to.variable, relativeImport(from, to));
  const code =
    column.code +
    (spec.required ? '.notNull()' : '') +
    (options.oneToOne ? '.unique()' : '') +
    `.references(() => ${to.variable}.id, { onDelete: '${onDelete}' })`;
  const comment = options.apiTags.length ? `/** @api ${options.apiTags.join(' ')} */\n` : '';
  file.addColumn(from.variable, key, code, comment, spec.after);
  if (!options.oneToOne) file.addIndex(from.variable, from.sql, key);

  // Same alias on both sides, so each relation finds its reverse.
  const alias = `${from.variable}${pascal(relation)}`;
  file.ensurePartTable(from.part, to.variable);
  file.addRelation(
    from.part,
    from.variable,
    relation.camel,
    `r.one.${to.variable}({ from: r.${from.variable}.${key}, to: r.${to.variable}.id${spec.required ? ', optional: false' : ''}, alias: '${alias}' })`,
  );
  if (options.inverse !== false)
    file.addRelation(
      from.part,
      to.variable,
      options.inverse,
      `r.${options.oneToOne ? 'one' : 'many'}.${from.variable}({ from: r.${to.variable}.id, to: r.${from.variable}.${key}, alias: '${alias}' })`,
    );
}

/** A junction table <owner><Target> in the owner's file, with both relations. */
function manyToMany(tables: Tables, owner: Table, target: Table, spec: FieldSpec) {
  if (owner.variable === target.variable) throw new Error('A many-to-many relation of a table with itself needs a hand-written junction table.');
  const file = tables.file(owner.path);
  if (!file.hasRelationsPart(owner.part))
    throw new Error(`${owner.path} has no "${owner.part}" (defineRelationsPart): add one before adding relations.`);

  const junction = `${owner.variable}${target.names.s.pascal}`;
  const sql = `${owner.sql}_${target.sql}`;
  if (file.tables().includes(junction)) throw new Error(`${owner.path} already has a ${junction} table.`);
  const ownerKey = `${owner.variable}Id`;
  const targetKey = `${target.variable}Id`;
  const ownerColumn = foreignKeyColumn(tables, owner, `${owner.sql}_id`);
  const targetColumn = foreignKeyColumn(tables, target, `${target.sql}_id`);

  for (const name of new Set([ownerColumn.builder, targetColumn.builder, 'mysqlTable', 'primaryKey', 'index']))
    file.ensureImport('drizzle-orm/mysql-core', name);
  if (owner.path !== target.path) file.importTable(target.variable, relativeImport(owner, target));
  file.addStatement(
    [
      `/** Links ${owner.names.p.lower} and ${target.names.p.lower} (many-to-many). */`,
      `export const ${junction} = mysqlTable(`,
      `  '${sql}',`,
      `  {`,
      `    ${ownerKey}: ${ownerColumn.code}.notNull().references(() => ${owner.variable}.id, { onDelete: 'cascade' }),`,
      `    ${targetKey}: ${targetColumn.code}.notNull().references(() => ${target.variable}.id, { onDelete: 'cascade' }),`,
      `  },`,
      `  (table) => [`,
      `    primaryKey({ columns: [table.${ownerKey}, table.${targetKey}] }),`,
      `    index('${sql}_${targetKey}_idx').on(table.${targetKey}),`,
      `  ],`,
      `);`,
    ].join('\n'),
    owner.part,
  );

  const relation = casings(words(spec.name)).camel;
  const inverse = spec.inverse === false ? false : (spec.inverse ?? owner.names.p.camel);
  file.ensurePartTable(owner.part, junction);
  file.ensurePartTable(owner.part, target.variable);
  file.addRelation(
    owner.part,
    owner.variable,
    relation,
    `r.many.${target.variable}({ from: r.${owner.variable}.id.through(r.${junction}.${ownerKey}), to: r.${target.variable}.id.through(r.${junction}.${targetKey}) })`,
  );
  if (inverse !== false)
    file.addRelation(
      owner.part,
      target.variable,
      inverse,
      `r.many.${owner.variable}({ from: r.${target.variable}.id.through(r.${junction}.${targetKey}), to: r.${owner.variable}.id.through(r.${junction}.${ownerKey}) })`,
    );
}

/**
 * Removes a column (with its indexes and, for a foreign key, its
 * relations), or a relation: a many-to-many drops its junction table, a
 * one-to-many drops the key on the other table.
 */
export function removeField(changes: Changes, resource: string, field: string): FieldResult {
  const tables = new Tables(changes);
  const owner = tables.find(resource);
  editable(owner);
  const result: FieldResult = { touched: [owner.names.p.kebab], dropped: {}, notes: [], foreignKey: false };
  const file = tables.file(owner.path);

  const key = [field, `${field}Id`, casings(words(field)).camel].find((k) => file.hasColumn(owner.variable, k));
  if (key) {
    removeColumn(tables, owner, key, result);
    tables.commit();
    return result;
  }

  // A relation without a column here, declared in this file or in the
  // file of the other table (which holds the key or the junction).
  const found = tables.findRelation(owner.variable, field);
  if (!found) throw new Error(`${owner.variable} has no "${field}" column or relation.`);
  const { config } = found;

  const junction = config.match(/\.through\(r\.(\w+)\./)?.[1];
  if (junction) {
    const { file: junctionFile, part } = found;
    const removed = junctionFile.removeRelations(part, new RegExp(`\\br\\.${junction}\\.`));
    junctionFile.removeStatement(junction);
    junctionFile.pruneUnusedPartTables(part);
    junctionFile.pruneImports();
    result.notes.push(`Removed the ${junction} junction table and ${removed.join(', ')}.`);
    tables.commit();
    return result;
  }

  // one-to-many: the key is on the other table, e.g. to: r.activity.customerId
  const other = config.match(/\bto:\s*r\.(\w+)\.(\w+)/);
  if (!other) throw new Error(`Can't tell where the key of ${owner.variable}.${field} is: remove it by hand.`);
  const [, otherTable, otherKey] = other;
  const target = tables.find(otherTable);
  editable(target);
  removeColumn(tables, target, otherKey, result);
  result.touched.push(target.names.p.kebab);
  tables.commit();
  return result;
}

function removeColumn(tables: Tables, table: Table, key: string, result: FieldResult) {
  const file = tables.file(table.path);
  (result.dropped[table.names.p.kebab] ??= []).push(key);
  const code = file.columnCode(table.variable, key) ?? '';
  file.removeColumn(table.variable, key);
  if (/\.references\(/.test(code) && file.hasRelationsPart(table.part)) {
    const removed = file.removeRelations(table.part, new RegExp(`\\br\\.${table.variable}\\.${key}\\b`));
    if (removed.length) result.notes.push(`Removed the relations ${removed.join(', ')}.`);
    file.pruneUnusedPartTables(table.part);
  }
  file.pruneImports();
}

/** Resources with a table the CLI can edit (all tables but Better Auth's). */
export function listResources(changes: Changes): string[] {
  const tables = new Tables(changes);
  return changes.list(TABLES)
    .filter((f) => f.endsWith('.ts') && `${TABLES}/${f}` !== AUTH)
    .flatMap((f) => tables.file(`${TABLES}/${f}`).tables())
    .map((variable) => resourceNames(variable).p.kebab);
}

/** Resources with a table, Better Auth's included (targets of a ref). */
export function listRefTargets(changes: Changes): string[] {
  const tables = new Tables(changes);
  return changes.list(TABLES)
    .filter((f) => f.endsWith('.ts'))
    .flatMap((f) => tables.file(`${TABLES}/${f}`).tables())
    .map((variable) => resourceNames(variable).p.kebab);
}

/**
 * What `field remove` can take for a resource: its columns (id aside) and
 * the relations that have no column here (one-to-many, many-to-many).
 */
export function listFields(changes: Changes, resource: string): { columns: string[]; relations: string[] } {
  const tables = new Tables(changes);
  const table = tables.find(resource);
  const columns = tables.file(table.path).columnKeys(table.variable).filter((key) => key !== 'id');
  const relations = new Set<string>();
  for (const name of changes.list(TABLES).filter((f) => f.endsWith('.ts'))) {
    const all = tables.file(`${TABLES}/${name}`).allRelations(table.variable);
    for (const [relation, config] of Object.entries(all)) {
      const ownKey = config.match(new RegExp(`from:\\s*r\\.${table.variable}\\.(\\w+)`))?.[1];
      // A key column of this table already stands for it (customer → customerId).
      if (ownKey && ownKey !== 'id' && columns.includes(ownKey)) continue;
      relations.add(relation);
    }
  }
  return { columns, relations: [...relations] };
}
